def merge(left, right):
    """合并两个有序列表;相等元素左段优先(<=)以保持稳定。"""
    res = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            res.append(left[i]); i += 1
        else:
            res.append(right[j]); j += 1
    res.extend(left[i:])
    res.extend(right[j:])
    return res

def sort(a):
    """自顶向下递归:从中点切两半,分别排序后合并。返回新列表。"""
    a = list(a)
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    left = sort(a[:mid])
    right = sort(a[mid:])
    return merge(left, right)

def _merge(a, lo, mid, hi, buf):
    """把有序的 a[lo:mid] 与 a[mid:hi] 合并写入 buf,再拷回 a。"""
    i, j, k = lo, mid, lo
    while i < mid and j < hi:
        if a[i] <= a[j]:          # <= 保持稳定
            buf[k] = a[i]; i += 1
        else:
            buf[k] = a[j]; j += 1
        k += 1
    while i < mid:
        buf[k] = a[i]; i += 1; k += 1
    while j < hi:
        buf[k] = a[j]; j += 1; k += 1
    a[lo:hi] = buf[lo:hi]

def sort(a):
    """自底向上迭代:宽度 1,2,4,8… 倍增,逐轮合并相邻有序块,免递归。"""
    a = list(a)
    n = len(a)
    buf = list(a)                 # 复用同一块 O(n) 缓冲区
    width = 1
    while width < n:
        for lo in range(0, n, 2 * width):
            mid = min(lo + width, n)        # 末段可能不足,统一 min 截断
            hi = min(lo + 2 * width, n)
            if mid < hi:
                _merge(a, lo, mid, hi, buf)
        width *= 2
    return a
